contract InvMutTest {
    C c;

    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function test(address recipient) public {
        require(recipient != address(0));
        require(recipient != address(this));

        uint256 balBefore = address(c).balance;
        uint256 recBefore = address(recipient).balance;

        c.withdrawAll(recipient); if (__ESBMC_reverted()) return;

        assert(address(recipient).balance == recBefore + balBefore);
    }
}

