pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Phishable as C} from "../src/Phishable.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function _test(address recipient) internal {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(this));
        uint256 balBefore = address(c).balance;
        uint256 recBefore = address(recipient).balance;
        try c.withdrawAll(recipient) {} catch { return; }
        assertTrue(address(recipient).balance == recBefore + balBefore);
    }

    function testFuzz_test(address recipient) public {
        _test(recipient);
    }

    receive() external payable {}
}
